/* RemoteFirstLeadership — Corporate / Executive theme with warm leadership accents */ .remote-sim-container { padding: 28px; background: #f4f6fa; min-height: 100vh; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1a2744; max-width: 1200px; margin: 0 auto; } .remote-sim-container h1, .remote-sim-container h3 { font-weight: 600; letter-spacing: -0.01em; } .remote-sim-header { background: linear-gradient(135deg, #1a2744 0%, #2d4068 100%); color: #ffffff; border-radius: 6px; padding: 28px 32px; margin-bottom: 24px; position: relative; overflow: hidden; } .remote-sim-header-bar { position: absolute; top: 0; left: 0; right: 0; height: 4px; background: linear-gradient(90deg, #f5b942, #c02f45, #4f8df5); } .remote-sim-header h1 { color: #ffffff; font-size: 1.6rem; margin: 0 0 6px 0; } .remote-sim-subtitle { color: #b8c5d9; font-size: 0.95rem; font-weight: 400; } .remote-sim-period-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; gap: 16px; flex-wrap: wrap; } .remote-sim-period-counter { background: #ffffff; border: 1px solid #d8dde8; border-radius: 4px; padding: 10px 18px; font-weight: 600; font-size: 0.95rem; color: #1a2744; } .remote-sim-period-counter span:nth-child(2) { color: #c02f45; font-size: 1.1rem; margin: 0 4px; } .remote-sim-round-tag { background: #1a2744; color: #f5b942; border-radius: 4px; padding: 10px 18px; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.08em; font-weight: 600; } .remote-sim-briefing { background: #ffffff; border: 1px solid #d8dde8; border-left: 4px solid #4f8df5; border-radius: 4px; padding: 20px 24px; margin-bottom: 24px; } .remote-sim-briefing-label { color: #2f66c4; font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.12em; font-weight: 700; margin-bottom: 8px; } .remote-sim-briefing-text { color: #2d3a52; font-size: 0.98rem; line-height: 1.55; } .remote-sim-status-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 28px; } .remote-sim-status-card { background: #ffffff; border: 1px solid #d8dde8; border-radius: 4px; padding: 20px 18px; position: relative; overflow: hidden; transition: transform 0.2s ease, box-shadow 0.2s ease; } .remote-sim-status-card:hover { transform: translateY(-2px); box-shadow: 0 4px 16px rgba(26,39,68,0.08); } .remote-sim-status-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; } .remote-sim-status-card.connection::before { background: #c02f45; } .remote-sim-status-card.speed::before { background: #4f8df5; } .remote-sim-status-card.retention::before { background: #f5b942; } .remote-sim-status-card.budget::before { background: #36b37e; } .remote-sim-label { color: #5c6779; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.1em; margin-bottom: 10px; font-weight: 600; } .remote-sim-value { font-size: 2.2rem; font-weight: 700; color: #1a2744; line-height: 1.1; } .remote-sim-sub { color: #646e7e; font-size: 0.78rem; margin-top: 6px; } .remote-sim-controls { background: #ffffff; border: 1px solid #d8dde8; border-radius: 4px; padding: 24px; margin-bottom: 24px; } .remote-sim-controls h3 { font-size: 1.1rem; margin: 0 0 8px 0; color: #1a2744; } .remote-sim-help { color: #5c6779; font-size: 0.88rem; margin-bottom: 18px; } .remote-sim-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; margin-bottom: 18px; } .remote-sim-input-group { display: flex; flex-direction: column; } .remote-sim-input-group label { font-size: 0.85rem; font-weight: 600; color: #1a2744; margin-bottom: 6px; } .remote-sim-controls input[type="number"], .remote-sim-controls select { background: #f8f9fc; border: 1px solid #c8d1e0; color: #1a2744; border-radius: 4px; padding: 9px 12px; width: 100%; font-size: 0.95rem; transition: border-color 0.2s ease, background 0.2s ease; } .remote-sim-controls input[type="number"]:focus, .remote-sim-controls select:focus { outline: none; border-color: #4f8df5; background: #ffffff; } .remote-sim-controls select option { background: #ffffff; color: #1a2744; } .remote-sim-hint { color: #646e7e; font-size: 0.75rem; margin-top: 5px; line-height: 1.35; } .remote-sim-totals { padding: 12px 16px; background: #f4f6fa; border-radius: 4px; font-size: 0.92rem; font-weight: 600; color: #1a2744; margin-bottom: 16px; } .remote-sim-totals #allocTotal { color: #c02f45; font-size: 1.05rem; } .remote-sim-btn-primary { background: #1a2744; border-color: #1a2744; padding: 10px 28px; font-weight: 600; letter-spacing: 0.02em; border-radius: 4px; transition: background 0.2s ease; } .remote-sim-btn-primary:hover { background: #2d4068; border-color: #2d4068; } .remote-sim-btn-undo { margin-left: 10px; border-radius: 4px; } .remote-sim-rituals { background: #ffffff; border: 1px solid #d8dde8; border-radius: 4px; padding: 24px; margin-bottom: 24px; } .remote-sim-rituals h3 { font-size: 1.1rem; margin: 0 0 16px 0; color: #1a2744; } .remote-sim-ritual-grid { display: flex; flex-direction: column; gap: 14px; } .remote-sim-ritual { display: grid; grid-template-columns: 220px 1fr 50px; gap: 14px; align-items: center; } .remote-sim-ritual-name { font-size: 0.9rem; font-weight: 600; color: #2d3a52; } .remote-sim-ritual-bar { height: 10px; background: #eef1f7; border-radius: 5px; overflow: hidden; } .remote-sim-ritual-fill { height: 100%; background: linear-gradient(90deg, #4f8df5, #36b37e); border-radius: 5px; transition: width 0.5s ease; } .remote-sim-ritual-pct { font-size: 0.85rem; font-weight: 600; color: #1a2744; text-align: right; } .remote-sim-coach { background: linear-gradient(135deg, #fff8eb 0%, #fdecd5 100%); border: 1px solid #f5b942; border-left: 4px solid #f5b942; border-radius: 4px; padding: 18px 22px; margin-bottom: 24px; } .remote-sim-coach-label { color: #8a5f0f; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.12em; font-weight: 700; margin-bottom: 6px; } .remote-sim-coach-text { color: #5a4210; font-size: 0.95rem; line-height: 1.5; font-style: italic; } .remote-sim-history { background: #ffffff; border: 1px solid #d8dde8; border-radius: 4px; padding: 24px; margin-bottom: 24px; } .remote-sim-history h3 { font-size: 1.1rem; margin: 0 0 14px 0; color: #1a2744; } .remote-sim-history table { font-size: 0.88rem; color: #2d3a52; margin-bottom: 0; } .remote-sim-history table thead th { background: #f4f6fa; color: #1a2744; font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.06em; border: none; padding: 10px 12px; } .remote-sim-history table tbody td { padding: 10px 12px; border-top: 1px solid #eef1f7; } .remote-sim-chart-wrap { background: #ffffff; border: 1px solid #d8dde8; border-radius: 4px; padding: 24px; margin-bottom: 24px; } .remote-sim-chart-wrap h3 { font-size: 1.1rem; margin: 0 0 14px 0; color: #1a2744; } .remote-sim-chart { position: relative; height: 320px; } @media (max-width: 768px) { .remote-sim-container { padding: 16px; } .remote-sim-header { padding: 20px; } .remote-sim-header h1 { font-size: 1.3rem; } .remote-sim-value { font-size: 1.7rem; } .remote-sim-grid { grid-template-columns: 1fr; } .remote-sim-ritual { grid-template-columns: 130px 1fr 40px; gap: 8px; } .remote-sim-ritual-name { font-size: 0.8rem; } .remote-sim-period-row { flex-direction: column; align-items: stretch; } .remote-sim-chart { height: 260px; } }

/* --- EQIL 2026-08-06: a11y + end-of-run debrief --- */
.remote-sim-completion {
    margin: 18px 0; padding: 22px 24px; border: 1px solid #d3dae6;
    border-left: 4px solid #2f66c4; border-radius: 6px;
    background: #ffffff; color: #1f2733;
}
.remote-sim-completion h3 { margin: 0 0 6px; font-size: 1.15rem; color: #1a2744; }
.remote-sim-completion .remote-sim-score { font-size: 2.1rem; font-weight: 700; line-height: 1.1; color: #1a2744; }
.remote-sim-completion .remote-sim-band {
    display: inline-block; margin-left: 10px; padding: 3px 12px; border-radius: 999px;
    background: #e8eefb; color: #2f66c4; font-size: 0.8rem; letter-spacing: 0.06em; text-transform: uppercase;
}
.remote-sim-completion .remote-sim-kpirow { margin: 14px 0; color: #4a5568; font-size: 0.9rem; }
.remote-sim-completion ul { margin: 10px 0 0 18px; }
.remote-sim-completion li { margin-bottom: 8px; }
button:focus-visible, input:focus-visible, select:focus-visible,
.remote-sim-completion:focus-visible { outline: 3px solid #2f66c4; outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) {
    * { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important; scroll-behavior: auto !important; }
}

