            var targetRisk = Math.max(5, 95 - (ds.connection * 7) - (avgRitual * 0.25));
            if (d.style === 'rto') targetRisk = Math.min(100, targetRisk + 35);
            ds.retentionRisk = ds.retentionRisk + (targetRisk - ds.retentionRisk) * 0.6;

            // Budget — in-person and human cost real EUR; effort points scale
            var budgetThisRound = (d.inperson * 350) + (d.human * 80) + (d.sync * 20) + (d.log * 10) + (d.async * 10);
            if (d.style === 'rto') budgetThisRound += 8000;
            ds.budgetSpent += budgetThisRound;

            // History
            ds.connectionHistory.push(parseFloat(ds.connection.toFixed(2)));
            ds.speedHistory.push(parseFloat(ds.decisionSpeed.toFixed(2)));
            ds.retentionHistory.push(Math.round(ds.retentionRisk));

            // Platform score: the same 0-100 roll-up getPerformanceSummary reports (connection 40, decision speed 30, inverted retention risk 30), on the rounded values this round returns.
            var pfConn = parseFloat(ds.connection.toFixed(1)) || 0;
            var pfSpeed = parseFloat(ds.decisionSpeed.toFixed(2)) || 0;
            var pfRisk = typeof ds.retentionRisk === 'number' ? Math.round(ds.retentionRisk) : 100;
            var pfScore = Math.round(Math.min(1, pfConn / 10) * 100 * 0.40 + Math.min(1, pfSpeed / 2) * 100 * 0.30 + (100 - Math.min(100, pfRisk)) * 0.30);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: Math.max(0, Math.min(100, pfScore)) });

            // Defer briefing + ritual bar update for next round
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
                self._renderRituals(state);
            }, 400);

            var retLabel = ds.retentionRisk > 70 ? window.mySimulation.t('risk_high')
                : ds.retentionRisk > 40 ? window.mySimulation.t('risk_medium')
                : window.mySimulation.t('risk_low');

            return {
                period: period,
                connection: parseFloat(ds.connection.toFixed(1)),
                decisionSpeed: parseFloat(ds.decisionSpeed.toFixed(2)),
                retentionRisk: Math.round(ds.retentionRisk),
                retentionLabel: retLabel,
                budgetThisRound: Math.round(budgetThisRound),
                budgetTotal: Math.round(ds.budgetSpent),
                style: d.style,
                styleNote: styleNote
            };
        }

