        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1].results || {};
            var conn = last.connection || 0;
            var speed = last.decisionSpeed || 0;
            // A retention risk of 0 is the best value, so only a missing value falls back to 100.
            var risk = typeof last.retentionRisk === 'number' ? last.retentionRisk : 100;
            var totalBudget = history.reduce(function(s, r) { return s + ((r.results && r.results.budgetThisRound) || 0); }, 0);

            var t = window.mySimulation.t.bind(window.mySimulation);

            var bandKey = 'perf_beginner';
            var insightKeys = [];
            if (conn >= 8 && speed >= 1.8 && risk <= 30) {
                bandKey = 'perf_excellent';
                insightKeys.push('insight_excellent');
            } else if (conn >= 6.5 && speed >= 1.2 && risk <= 50) {
                bandKey = 'perf_good';
                insightKeys.push('insight_good');
            } else {
                insightKeys.push('insight_beginner');
            }

            if (conn < 6) insightKeys.push('insight_low_conn');
            if (speed < 1) insightKeys.push('insight_low_speed');
            if (risk > 60) insightKeys.push('insight_high_risk');

            // 0-100 roll-up for the reporting layer, from the three KPIs the bands already use.
            // connection is /10, decision speed tops out at 2.0 in play, retention risk is inverted.
            var overall = Math.max(0, Math.min(100, Math.round(
                Math.min(1, conn / 10) * 100 * 0.40
                + Math.min(1, speed / 2) * 100 * 0.30
                + (100 - Math.min(100, risk)) * 0.30
            )));

            var summary = {
                connection: conn,
                decisionSpeed: speed,
                retentionRisk: risk,
                totalBudget: totalBudget,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                performance: t(bandKey),
                performanceKey: bandKey,
                insightKeys: insightKeys,
                insights: insightKeys.map(function(k) { return t(k); })
            };

            try {
                if (window.mySimulation && window.mySimulation.state) {
                    window.mySimulation.state.performance = summary;
                }
            } catch (e) { /* non-fatal */ }

            return summary;
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var finished = period > this.ROUNDS.length;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            if (idx < 0) idx = 0;
            var round = this.ROUNDS[idx];
            if (!window.mySimulation) return;
            var t = window.mySimulation.t.bind(window.mySimulation);
            var tagEl = document.getElementById('roundTag');
            var briefEl = document.getElementById('briefingText');
            var coachEl = document.getElementById('coachText');
            if (tagEl) tagEl.textContent = finished ? t('end_tag') : t(round.tagKey);
            if (briefEl) briefEl.innerHTML = finished ? t('end_body') : t(round.briefKey);
            if (coachEl) coachEl.textContent = finished ? t('end_coach') : t('coach_r' + (idx + 1));

            var panel = document.getElementById('completionPanel');
            if (finished) {
                this._showCompletion();
            } else if (panel) {
                panel.style.display = 'none';
                panel.innerHTML = '';
            }
        }

        _showCompletion() {
            var panel = document.getElementById('completionPanel');
            if (!panel) return;
            var sim = window.mySimulation;
            var html = sim && sim.lastCompletionHTML;
            if (!html && sim && sim.lastSummary && this.formatCompletionMessage) {
                html = this.formatCompletionMessage(sim.lastSummary);
            }
            if (!html) return;
            panel.innerHTML = html;
            panel.style.display = 'block';
            if (typeof panel.focus === 'function') { try { panel.focus(); } catch (e) {} }
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = window.mySimulation.t.bind(window.mySimulation);
            var items = (summary.insightKeys || []).map(function(k) { return '<li>' + t(k) + '</li>'; }).join('');
            return ''
                + '<h3>' + t('completion_title') + '</h3>'
                + '<div><span class="remote-sim-score">' + (summary.overallScore || 0) + '<span style="font-size:1rem">/100</span></span>'
                + '<span class="remote-sim-band">' + (summary.performance || '') + '</span></div>'
                + '<div class="remote-sim-kpirow">'
                + t('kpi_connection') + ': <b>' + (summary.connection || 0) + '</b> &middot; '
                + t('kpi_speed') + ': <b>' + (summary.decisionSpeed || 0) + '</b> &middot; '
                + t('kpi_risk') + ': <b>' + Math.round(summary.retentionRisk || 0) + '</b> &middot; '
                + t('kpi_budget') + ': <b>' + Math.round(summary.totalBudget || 0) + '</b>'
                + '</div>'
                + (items ? '<p><b>' + t('completion_insights') + '</b></p><ul>' + items + '</ul>' : '')
                + '<p>' + t('completion_thanks') + '</p>';
        }

        _renderRituals(state) {
            if (!state.domainState || !state.domainState.rituals) return;
            var r = state.domainState.rituals;
            var pairs = [
                ['async', r.async], ['log', r.log], ['sync', r.sync], ['human', r.human], ['inperson', r.inperson]
            ];
            pairs.forEach(function(p) {
                var bar = document.getElementById(p[0] + 'Bar');
                var pct = document.getElementById(p[0] + 'Pct');
                var v = Math.round(p[1]);
                if (bar) bar.style.width = v + '%';
                if (pct) pct.textContent = v + '%';
            });
        }

